<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    create </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0640</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deploy deploy  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 轮转后用指定属主重建新日志文件</span></span>
